sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float speed;
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    float k = 1.0 + amount * (0.5 + 0.5 * sin(time * speed));
    return half4(saturate(c.rgb * half(k)) * c.a, c.a);
}
